[
  {
    "statement": "A global review on setting a minimum landing size for commercially fished species found that one of five swordfish fisheries showed an increase in recruitment after implementing recommended minimum landing sizes and catch limits.",
    "citations": [
      "2735"
    ]
  },
  {
    "statement": "A study in the Ionian Sea reported that despite established minimum sizes, most commercially landed fish were immature and had not yet spawned.",
    "citations": [
      "2735"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of setting a maximum landing size on marine fish populations.",
    "citations": [
      "2736",
      "2737"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of specifying a size range for commercially fished species on marine fish populations.",
    "citations": [
      "2736",
      "2737"
    ]
  }
]

[
  {
    "statement": "The long-term closure of a commercial fishery for lesser sandeel resulted in a reduction of overall fishing effort for that species.",
    "citations": [
      "2655"
    ]
  },
  {
    "statement": "Annual sandeel catch rates were varied after the closure of a commercial fishery for sandeel.",
    "citations": [
      "2655"
    ]
  },
  {
    "statement": "In an area that had been closed to fishing for eight years, six out of seven fish species were more vulnerable to capture by spear guns.",
    "citations": [
      "2655"
    ]
  },
  {
    "statement": "None of the studies that were reviewed had any information on the social or community response to long-term fishery closures.",
    "citations": [
      "2655"
    ]
  }
